import test from "node:test";
import assert from "node:assert/strict";
import { createServer } from "node:http";
import { once } from "node:events";
test("GET /tasks/1", async t => {
  const server = createServer((req, res) => {
    const found = req.method === "GET" && req.url === "/tasks/1";
    res.writeHead(found ? 200 : 404, {"Content-Type":"application/json"});
    res.end(JSON.stringify(found ? {id:1,title:"Lire"} : {error:"Absente"})); });
  t.after(() => new Promise(resolve => server.close(resolve)));
  server.listen(0, "127.0.0.1"); await once(server, "listening");
  const url = "http://127.0.0.1:" + server.address().port;
  const response = await fetch(url + "/tasks/1");
  assert.strictEqual(response.status, 200);
  assert.deepStrictEqual(await response.json(), {id:1,title:"Lire"});
});

import { test, expect } from "vitest";
const pending = tasks => tasks.filter(t => !t.done);
test("garde les tâches non terminées", () => {
  const tasks = [{id:1, done:false}, {id:2, done:true}];
  const result = pending(tasks);
  expect(result).toEqual([{id:1, done:false}]);
});

import express from "express";
const app = express();
app.use(express.json());
const tasks = [{id:1, title:"Lire"}];
const repo = { find: id => tasks.find(t => t.id === id) };
const service = id => repo.find(id);
app.get("/tasks/:id", (req, res) => {
  const id = Number(req.params.id);
  if (!Number.isInteger(id) || id < 1)
    return res.status(400).json({error:"Id invalide"});
  const task = service(id);
  return task ? res.json(task) : res.status(404).json({error:"Absente"});
});
app.use((err, req, res, next) =>
  res.status(err.status || 500).json({error:"Incident"}));
app.listen(3000, "127.0.0.1");

