import { useState } from 'react';
function Name({ name, onName }) {
  return <input aria-label="Prénom" value={name}
    onChange={e => onName(e.target.value)} />;
}
export default function App() {
  const [name, setName] = useState('');
  const [count, setCount] = useState(0);
  const items = [{ id: 1, title: 'Lire' }, { id: 2, title: 'Marcher' }];
  return <main>
    <Name name={name} onName={setName} />
    <p>Bonjour {name || 'visiteur'} — {count}</p>
    <button onClick={() => setCount(n => n + 1)}>Ajouter</button>
    <ul>{items.map(item => <li key={item.id}>{item.title}</li>)}</ul>
  </main>;
}

import { useEffect, useState } from 'react';
async function load(id) {
  if (id !== 'lire') throw new Error('Activité inconnue'); return 'Lire';
}
function Detail({ id }) {
  const [state, set] = useState({ loading: true, text: '' });
  useEffect(() => {
    let active = true; set({ loading: true, text: '' });
    async function run() {
      try { const text = await load(id); if (active) set({loading:false,text}); }
      catch (e) { if (active) set({ loading: false, text: e.message }); }
    }
    run(); return () => { active = false; };
  }, [id]);
  return <p>{state.loading ? 'Chargement…' : state.text}</p>;
}

